// [время первого слова фразы, описание кадра, v (что рисовать), доп. поля (in, sfx, amb)]
// Все персонажи одного размера (FIX_S в director.js), камера без зума. Ускорение = синеватый «замёрзший» мир (fx.freeze).
import fs from 'node:fs';
const DIR = new URL('.', import.meta.url).pathname;
const words = JSON.parse(fs.readFileSync(DIR + '../timeline/words.json', 'utf8'));
const W = words.words || words;
const DURATION = Math.round((W[W.length - 1].end + 1.2) * 100) / 100;
const norm = (s) => s.toLowerCase().replace(/ё/g, 'е').replace(/[^а-яa-z0-9]/g, '');
const w = (pref, after) => { const p = norm(pref); const x = W.find((q) => q.start >= after - 0.01 && norm(q.word).startsWith(p)); if (!x) throw new Error('нет слова ' + pref + ' после ' + after); return x.start; };

// ── сокращения
const mk = (k) => (o = {}) => ({ w: k, ...o });
const art = mk('artem'), leh = mk('leha'), mom = mk('mom'), gran = mk('gran'), lady = mk('lady'), cash = mk('cash'), girl1 = mk('girl1'), girl2 = mk('girl2'), umbr = mk('umbr'), doc = mk('doc'), trauma = mk('trauma'), passer = mk('passer');
const FZ = { freeze: true };                       // ускорение включено
const RAIN = (o = {}) => ({ set: 'city', so: { mood: 'storm', rain: true, ...o }, fx: { rain: true } });
const RAINF = (o = {}) => ({ set: 'city', so: { mood: 'storm', rain: true, ...o }, fx: { freeze: true }, pf: [{ t: 'rainhang' }] });
const CITY = (o = {}) => ({ set: 'city', so: o });
const CROSS = (o = {}) => ({ set: 'city', so: { zebra: 120, tl: -520, ...o } });
const KITCH = (o = {}) => ({ set: 'kitchen', so: { fridgeX: -560, shelfX: 200, ...o } });
const GKIT = (o = {}) => ({ set: 'gkitchen', so: o });
const ROOM = (o = {}) => ({ set: 'myroom', so: o });
const ROOMN = (o = {}) => ({ set: 'myroom', so: { night: true, ...o } });
const SHOP = (o = {}) => ({ set: 'shop', so: o });
const COR = { set: 'hallway' }, CLIN = { set: 'clinic' }, CAB = { set: 'cabinet' }, CINE = { set: 'cinema' };
const ROOF = (o = {}) => ({ set: 'roof', so: o });
const VOID = (light = '#8fb8e8', mood = 'void') => ({ set: 'void', so: { light, mood } });
const ins = (base, k, o = {}) => ({ ...base, ins: { k, ...o } });
const bp = (k, o = {}) => ({ bp: { k, ...o } });
const sfx = (...a) => ({ sfx: a.map(([at, name, gain = -10]) => ({ at, name, gain })) });
const big = (s, y = 300, at = 0.3) => ({ k: 'big', s, at, y, band: true });
const badge = (s, at = 0.5) => ({ k: 'badge', s, at });
const thought = (s, at = 0.5) => ({ k: 'thought', s, at, band: true });
const BIG = (s, light = '#ffb070', mood = 'dusk') => ({ ...VOID(light, mood), ui: [big(s, 540, 0.2)] });
const ON = (extra = {}) => ({ ...sfx([0.1, 'freeze', -12]), ...extra });   // звук включения ускорения
const OFF = (extra = {}) => ({ ...sfx([0.1, 'whoosh', -12]), ...extra });
const PIG = (x, h = 560) => ({ t: 'pigeon', x, h });
const PIGS = [PIG(-640, 600), PIG(-160, 700), PIG(420, 560), PIG(760, 660)];

